67-/** Quantisation actually observed in the numbers themselves (a cross-check on the claim). */
68-export function observedQuantum(vec) {
69-  if (!isVec3(vec)) return null;
70-  // coarsest first: the observed quantum is the LARGEST step every component fits
71-  for (const q of [1e-1, 1e-2, 1e-3]) {
72-    if (vec.slice(0, 3).every((n) => Math.abs(n / q - Math.round(n / q)) < 1e-6)) return q;
73-  }
74-  return null;
75-}
