82:export function selectPlayerPose(sample) {
83-  const s = sample ?? {};
84-  const snapshot = s.journeySnapshot ?? null;
85-  let primary = null;
86:  for (const path of SNAPSHOT_POSE_CANDIDATES) {
87-    const v = readPath(snapshot, path);
88-    if (isVec3(v)) { primary = { pos: [v[0], v[1], v[2]], path }; break; }
89-  }
90-  const autoPos = s.autopilot?.pos ?? null;
